  "lesson.library.t": "The library",
  "lesson.library.d": "Read a book, learn what you choose",
  "lesson.library.take": "Books raise your Intellect and teach you recipes. Face the shelf, press %KeyE% and choose a subject",
  "lesson.library.takeTouch": "Books raise your Intellect and teach you recipes. Face the shelf, tap the action button and choose a subject",
  "lesson.library.sit": "Book in hand. Follow the arrows to a free chair and press %KeyE% to sit and read",
  "lesson.library.sitTouch": "Book in hand. Follow the arrows to a free chair and tap the action button to sit and read",
  "lesson.library.read": "When a key word lights up, press %KeyE%: the marker waits for you there. Each one speeds the set. The bar fills anyway, so there’s no rush",
  "lesson.library.readTouch": "When a key word lights up, tap the page: the marker waits for you there. Each one speeds the set. The bar fills anyway, so there’s no rush",
  "lesson.library.over": "+2 Intellect. Every 5 points, a book tells you a recipe from its subject. Six sets a day, then your head’s full. Ask the librarian what to read",
  "lesson.library.left": "You put the book back. Try the lesson again",
  "help.library.t": "The library",
  "help.library.hook": "Books, subjects and Intellect",
  "help.library.sum": "Read books to raise your Intellect and learn the recipes you choose. Better jobs and smarter recipes open as it climbs.",
  "help.library.steps": "Open a library shelf and choose a subject: tools, locks and fakes, weapons or everyday things.\nBook in hand, sit at a table and press the action button (with no chair free, you read at the shelf).\nA marker reads along the page and waits at each key word as it lights up: press then (anywhere on the page will do). Each one speeds the set; pressing when nothing’s lit costs you the next.\nA set is +2 Intellect for 10 energy. The bar fills anyway, so a slow reader still finishes.",
  "help.library.lh": "Ways to learn",
  "help.library.list": "Books: six sets a day, then your head’s full until tomorrow.\nThe kiosk: a course a day, +3 if you pass.\nCheckers with the old-timer: +1 a day, and +1 for any win.\nQuiz night: +2 if you win.",
  "help.library.tip": "Every 5 points of Intellect, a book tells you a recipe from its subject. In free time the librarian sits at a table: ask what to read.",
  "box.read": "Read a book",
  "box.readNote": "+2 Intellect a set · {n} energy · {d} of {max} today",
