  "role.librarian": "Librarian",
  "talk.librarianTry": "Looking for something? Try {subject}: there are {n} things in there for you.",
  "talk.librarianTryOne": "Looking for something? Try {subject}: there is one thing in there for you.",
  "talk.librarianNothing": "Nothing new for you on these shelves yet. {next}.",
  "talk.librarianFull": "That's enough for one day. Your head needs the night: come back tomorrow.",
  "toast.headFull": "Your head's full: no more reading today",
  "hint.readSit": "Book in hand: sit at a table to read it. The arrows show a free chair.",
  "hint.readKeys": "Press %KeyE% when a key word lights up: the marker waits for you, a few seconds. Each one speeds the set; pressing when nothing’s lit costs you the next. The bar fills anyway. Six sets a day.",
  "hint.readTouch": "Tap anywhere on the page when a key word lights up: the marker waits for you, a few seconds. Each one speeds the set; tapping when nothing’s lit costs you the next. The bar fills anyway. Six sets a day.",
  "book.tools": "Tools",
  "book.locks": "Locks and fakes",
  "book.weapons": "Weapons",
  "book.everyday": "Everyday things",
  "book.tools.title": "Tools and Trades",
  "book.locks.title": "Locks and Fakes",
  "book.weapons.title": "Self-Defence",
  "book.everyday.title": "Everyday Know-How",
  "book.tools.p0": "A good [handle] is half the tool. Choose [hard wood], cut it to [length], and bind the [head] with tape [pulled tight] until it can't [shift].",
  "book.tools.p1": "To [dig] well, keep your [back straight] and let the [weight] do the work. A [blunt edge] tires you fast, so [file it] before you [begin].",
  "book.tools.p2": "Rope holds best with a [flat knot]. Test each [loop] with your [full weight], low down, before you [trust it] with a [long drop] [below].",
  "book.locks.p0": "Every [lock] is a row of [pins] held by a [spring]. Lift each pin to the [shear line] and the [plug] will [turn].",
  "book.locks.p1": "A copy fools the eye at [ten paces]. Match the [colour] first, then the [shadow]. A wall looks real when the [seams] are [straight] and the [dust] even.",
  "book.locks.p2": "[Paper] soaked in [glue] dries as hard as [plaster]. Press it into a [mould], let it [set] overnight, and [paint] it last.",
  "book.weapons.p0": "Stand with your [feet apart] and your [weight low]. A [fast blow] beats a [hard one] if you [keep moving] and [breathe out].",
  "book.weapons.p1": "A [short swing] gives less warning. Aim for the [arm] that holds the [weapon], then [step back] out of [reach], and [wait].",
  "book.weapons.p2": "[Padding] under a shirt takes the [sting] from a blow. Keep it [light] or you [lose speed], and [know] when to [run].",
  "book.everyday.p0": "[Fruit] and [sugar] in a sealed [bag] will [ferment] in days. Keep it [warm], and let the [gas] out.",
  "book.everyday.p1": "A [battery], some [wire] and a [bell] make an alarm. [Strip] the ends, [twist] them tight and [tape] it all.",
  "book.everyday.p2": "A [dog] or a [rat] trusts [food] before it trusts a [hand]. Be [patient], and come back at the [same hour].",
