  "hint.meal": "Take a tray at the serving counter, then sit at a table to eat it: +{n} energy, once a meal",
  "hint.rollCall": "Stand on your orange square: it's the only place you're counted. A guard walks the line with a clipboard: when you're called, press the action button",
  "hint.shower": "Under a shower, the action button turns it on: energy back and a little heat off while it runs. Walk away to stop",
  "hint.showerHostile": "Under a shower, the action button turns it on: energy back and a little heat off while it runs. Watch your back: scores get settled in here",
  "hint.stay": "Stay until the badge at the top fills up: {n} minutes here and you're checked in. Slip away before, and a guard who sees you will mind",
  "hint.sit": "Sitting rests you: energy comes back. Move or press the button to get up",
  "hint.rest": "Resting in the infirmary: energy and health come back faster. Move to get up",
  "hint.mealTable": "Sit at a table to eat your tray: +{n} energy, once a meal",
  "hint.tray": "Now sit at a table to eat",
  "hint.trayBack": "Take the empty tray back to the counter, or it's +{n}% heat",
  "toast.trayHeat": "Tray not brought back: +{n}% heat",
  "toast.noTray": "Nothing to eat: take a tray at the serving counter first",
  "float.trayDropped": "Tray dropped",
  "float.trayLeft": "Tray left behind",
  "float.trayOver": "The meal's over",
  "act.takeTray": "Take a tray",
  "act.shower": "Shower",
  "act.here": "Here!",
  "act.returnTray": "Put the tray back",
  "float.meal": "+{n} energy",
  "float.lap": "Lap!",
  "toast.fresh": "Fresh from the garden: +{n} energy and health",
  "hint.sports": "The sports field: run laps of the track for Speed (every corner in order, back to where you started), lift weights or do pull-ups for Strength, take penalties and shoot hoops. Open in free time and the exercise hour",
  "hint.gardenPlace": "The vegetable garden: your own beds to plant and water, and the gardener's planters (a job at the board). When you fill the gardener's crates, the meals are fresh for a day",
  "lesson.walk.t": "Walking",
  "lesson.walk.d": "Get around and follow the floor arrows",
  "lesson.walk.out": "Walk out of your cell with %KeyW% %KeyA% %KeyS% %KeyD% (or click where to go)",
  "lesson.walk.outTouch": "Drag anywhere to walk out of your cell (or tap where to go)",
  "lesson.walk.arrows": "Follow the arrows on the floor to the woodshop. The wheel zooms",
  "lesson.walk.arrowsTouch": "Follow the arrows on the floor to the woodshop. Pinch to zoom",
  "lesson.search.t": "Searching",
  "lesson.search.d": "Desks, pockets and holding things",
  "lesson.search.desk": "Face your desk and press %KeyE% to search it",
  "lesson.search.deskTouch": "Face your desk and tap the action button to search it",
  "lesson.search.take": "Click the magazine, then an empty pocket (or click it twice)",
  "lesson.search.takeTouch": "Tap the magazine, then an empty pocket (or tap it twice)",
  "lesson.search.hold": "Close the desk, then hold the magazine: press its number (1–6)",
  "lesson.search.holdTouch": "Close the desk, then tap the magazine's pocket to hold it",
  "lesson.craft.t": "Crafting",
  "lesson.craft.d": "Two items into one",
  "lesson.craft.open": "Open crafting: %KeyC% or the hammer button",
  "lesson.craft.openTouch": "Open crafting: the hammer button",
  "lesson.craft.make": "Put the magazine and the duct tape on the workbench, then make the poster",
  "lesson.routine.t": "The routine",
  "lesson.routine.d": "Bells, roll call and Lights Out",
  "lesson.routine.bell": "The bell is about to ring for evening roll call…",
  "lesson.routine.yard": "Roll call: follow the arrows to your spot in the yard, and stay until the badge at the top fills up: then you're counted",
  "lesson.routine.wait": "Checked in. Time passes until Lights Out…",
  "lesson.routine.home": "Lights Out: back to your cell before the door locks",
  "lesson.routine.sleep": "Face your bed and press %KeyE% to sleep",
  "lesson.routine.sleepTouch": "Face your bed and tap the action button to sleep",
  "lesson.routine.missed": "You missed roll call: try the lesson again, and follow the arrows as soon as the bell rings",
  "lesson.heat.t": "Heat and guards",
  "lesson.heat.d": "What guards see, and what it costs",
  "lesson.heat.show": "Hold the cutters (1) and step into the guard's cone: watch the heat climb",
  "lesson.heat.showTouch": "Hold the cutters (tap their pocket) and step into the guard's cone: watch the heat climb",
  "lesson.heat.hide": "Quick, hide them: hold an empty pocket (2). At 80% heat the guards chase you",
  "lesson.heat.hideTouch": "Quick, hide them: tap an empty pocket. At 80% heat the guards chase you",
  "lesson.stash.t": "Hiding things",
  "lesson.stash.d": "The desk's secret compartment",
  "lesson.stash.desk": "Contraband in your pockets is found when you're caught. Open your desk (%KeyE%)",
  "lesson.stash.deskTouch": "Contraband in your pockets is found when you're caught. Open your desk with the action button",
  "lesson.stash.hide": "Click the cutters, then a slot of the Hidden compartment (or click them twice): searches never find it",
  "lesson.stash.hideTouch": "Tap the cutters, then a slot of the Hidden compartment (or tap them twice): searches never find it",
  "lesson.dig.t": "Tools",
  "lesson.dig.d": "Chip a wall and cover your tracks",
  "lesson.dig.chip": "The pickaxe is in hand: keep %Space% held to chip the wall in front of you",
  "lesson.dig.chipTouch": "The pickaxe is in hand: keep the Chip button held to chip the wall in front of you",
  "lesson.dig.cover": "A hole is evidence. Hold the poster (2) and press %Space% facing the hole to cover it (%KeyE% takes a poster back off)",
  "lesson.dig.coverTouch": "A hole is evidence. Tap the poster's pocket, then the Cover button",
  "lesson.fight.t": "Fighting",
  "lesson.fight.d": "Lock on, block and land your blows",
  "lesson.fight.lock": "Sparky wants a sparring match. Press %KeyR% to lock on to him",
  "lesson.fight.lockTouch": "Sparky wants a sparring match. Tap him to lock on",
  "lesson.fight.first": "Close in and hit him with %Space%: he'll hit back",
  "lesson.fight.firstTouch": "Close in and tap Hit: he'll hit back",
  "lesson.fight.block": "Hold %KeyV% to block as he swings: a blocked blow does half the damage",
  "lesson.fight.blockTouch": "Hold the shield button to block as he swings: a blocked blow does half the damage",
  "lesson.fight.hit": "Now hit with %Space% until he's out cold. (%KeyR% again lets go of him; your nunchucks are equipped)",
  "lesson.fight.hitTouch": "Now tap Hit until he's out cold. (Your nunchucks are equipped)",
  "lesson.escape.t": "Getting out",
  "lesson.escape.d": "The power, the fence, the road",
  "lesson.escape.room": "Your plastic key opens the purple door: go into the generator room",
  "lesson.escape.power": "Face the generator and press %KeyE% once to switch off the power (again switches it back on)",
  "lesson.escape.powerTouch": "Face the generator and tap the action button once to switch off the power (again switches it back on)",
  "lesson.escape.fence": "45 seconds without power (the pill at the top counts down): follow the arrows to the fence, face it and keep %Space% held to cut it. Back on, it shocks",
  "lesson.escape.fenceTouch": "45 seconds without power (the pill at the top counts down): follow the arrows to the fence, face it and keep the Cut button held. Back on, it shocks",
  "lesson.escape.out": "Through the hole and out onto the road!",
