  "lesson.noise.throw": "Hold the right mouse button over the floor to aim the potato, then let go to throw it",
  "lesson.noise.throwTouch": "Tap the potato in your hand, then Throw: drag to aim, lift to throw",
  "lesson.noise.bang": "A potato doesn't carry far. A firecracker does: hold it (2) and throw it into the gym",
