  "pa.dismiss": "Tap to close",
  "pa.dismissKeys": "Click or press Esc to close",
  "pa.hello.center-perks.0": "Good morning, Center Perks! Chins up, beds made, smiles on.",
  "pa.hello.center-perks.1": "Morning, everyone. Warden Hartley here, with today's notices.",
  "pa.hello.center-perks.2": "Morning. Somebody left a sock in the soup again. Again.",
  "pa.hello.stalag-flucht.0": "Attention, prisoners! A crisp, fine morning. Do enjoy it inside the wire.",
  "pa.hello.stalag-flucht.1": "Attention. The Kommandant's orders for the day follow.",
  "pa.hello.stalag-flucht.2": "Attention! Last night someone tunnelled into the kitchen. The kitchen. Ach.",
  "pa.hello.shankton.0": "Rise and shine, Shankton. It's a great day to follow the rules.",
  "pa.hello.shankton.1": "This is Warden Kroll. Listen up, because I say this once.",
  "pa.hello.shankton.2": "Kroll here. I haven't had my coffee. Don't test me.",
  "pa.hello.san-pancho.0": "¡Buenos días, mis amigos! El Jefe loves you all. Mostly.",
  "pa.hello.san-pancho.1": "El Jefe speaking. Today's news, from the top.",
  "pa.hello.san-pancho.2": "El Jefe is not happy. Someone stole his favourite hammock.",
  "pa.hello.irongate.0": "Good morning, residents of Irongate. The sea sends its regards.",
  "pa.hello.irongate.1": "Governor Ashcombe. The day's arrangements are as follows.",
  "pa.hello.irongate.2": "Governor here. My tea was cold. Consider everyone warned.",
  "pa.first.center-perks": "Welcome to Center Perks, new arrival. Follow the bell and we'll get along fine.",
  "pa.first.stalag-flucht": "Welcome to Stalag Flucht. Escape is forbidden. Also, it is very cold.",
  "pa.first.shankton": "Welcome to Shankton. Walls: thick. Guards: many. Questions: none.",
  "pa.first.san-pancho": "Welcome to San Pancho, amigo! Mind the mines, mind the sun, mind El Jefe.",
  "pa.first.irongate": "Welcome to Irongate. Nobody leaves. The sea sees to that.",
  "pa.morning.none": "Nothing special on today. Let's keep it dull.",
  "pa.morning.inspection": "Inspectors from the ministry arrive at {time}. Clean cells, clean manners.",
  "pa.morning.drill": "There will be a fire drill today. When the bell rings, walk to the yard. Walk.",
  "pa.morning.feast": "Tonight's dinner is a feast. Yes, real gravy.",
