  // P27 lessons: Cheat, hoops, checkers.
  "lesson.cards.t": "Cheat",
  "lesson.cards.d": "Bluffing at cards, and calling a liar",
  "lesson.cards.start": "Talk to Sparky (%KeyE%) and play Cheat for $5",
  "lesson.cards.startTouch": "Talk to Sparky (the action button) and play Cheat for $5",
  "lesson.cards.lay": "Pick 1 to 3 cards (keys 1 to 5) and lay them (Enter) as the table card: true, or a bluff",
  "lesson.cards.layTouch": "Tap 1 to 3 cards and lay them as the table card: true, or a bluff",
  "lesson.cards.call": "Watch his play, and his tell: call Liar! (L) when you doubt him, or lay more on top",
  "lesson.cards.callTouch": "Watch his play, and his tell: tap Liar! when you doubt him, or lay more on top",
  "lesson.cards.end": "Whoever was wrong lost a chip. Play the hand out: the last chip lost loses the stake",
  "lesson.cards.folded": "The game's over before its end (walking away folds it). Try the lesson again",
  "lesson.hoops.t": "Hoops",
