  "lesson.hoops.shoot": "Stand on a spot painted by the hoop and shoot: hold %Space%, let go",
  "lesson.hoops.shootTouch": "Stand on a spot painted by the hoop and shoot: hold Shoot, let go",
  "lesson.hoops.basket": "Now a basket: let go with the marker in the green (dead in its middle, nothing but net)",
  "lesson.hoops.basketTouch": "Now a basket: let go of Shoot with the marker in the green (dead in its middle, nothing but net)",
  "lesson.hoops.shootout": "Now a shootout: talk to Sparky (%KeyE%) and press To the hoop",
  "lesson.hoops.shootoutTouch": "Now a shootout: talk to Sparky (the action button) and tap To the hoop",
  "lesson.hoops.finish": "Shoot from each lit spot in turn, then he does: most baskets wins",
  "lesson.hoops.off": "The shootout's off (you left the court). Try the lesson again",
  "lesson.checkers.t": "Checkers",
  "lesson.checkers.d": "The old-timer's game, and his secrets",
  "lesson.checkers.sit": "Every prison has an old-timer who plays checkers. Here it's Sparky: talk to him (%KeyE%), choose Carry on, and finish the game he's left set up",
