  // P28 lessons: pruno, the garden, rat racing.
  "lesson.pruno.t": "Pruno",
  "lesson.pruno.d": "Brew it, hide it, wait for it",
  "lesson.pruno.brew": "Fruit (off the canteen counter at meals) and sugar (from the kitchen, or a merchant) make pruno. Open crafting (%KeyC%) and brew a bag from your two fruit and the sugar",
  "lesson.pruno.brewTouch": "Fruit (off the canteen counter at meals) and sugar (from the kitchen, or a merchant) make pruno. Open crafting (the hammer button) and brew a bag from your two fruit and the sugar",
  "lesson.pruno.hide": "It ferments only out of your pockets. Hide it in your toilet's tank (%KeyE%): searches never look there, but a passing dog smells it",
  "lesson.pruno.hideTouch": "It ferments only out of your pockets. Hide it in your toilet's tank (the action button): searches never look there, but a passing dog smells it",
  "lesson.pruno.sleep": "Two nights to ripen. The bag you hid in your desk two nights ago will be ready by morning: sleep in your bed (%KeyE%)",
  "lesson.pruno.sleepTouch": "Two nights to ripen. The bag you hid in your desk two nights ago will be ready by morning: sleep in your bed (the action button)",
  "lesson.pruno.drink": "Ripe! Take it from your desk's hidden drawer and drink it: %Space% twice with it in hand (the first press asks if you're sure)",
  "lesson.pruno.drinkTouch": "Ripe! Take it from your desk's hidden drawer and drink it: the Drink button twice with it in hand (the first tap asks if you're sure)",
  "lesson.pruno.over": "Tipsy for 3 hours: harder blows, a slower walk, and a guard who sees you adds heat. Ripe pruno also sells for $30, or makes a fine gift",
  "lesson.garden.t": "The garden",
  "lesson.garden.d": "Seeds, water and a secret",
  "lesson.garden.plant": "The vegetable garden's beds: face an empty bed and press %Space% with the seed packet in hand to plant it",
