  "lesson.talent.t": "Talent night",
  "lesson.talent.d": "A song played in time, on the canteen's stage",
  "lesson.talent.watch": "It's talent night: two or three inmates play first, and their marks show as they finish. Your turn comes after the last act",
  "lesson.talent.stage": "Step onto the stage, pick a song and the bucket drums, and press Perform",
  "lesson.talent.stageTouch": "Step onto the stage, pick a song and the bucket drums, and tap Perform",
  "lesson.talent.play": "Play each note as it reaches the line (%KeyA% %KeyS% %KeyD% or ← ↓ →). On the beat is perfect; a press with no note near costs you",
  "lesson.talent.playTouch": "Tap a lane's pad as its note reaches the line. On the beat is perfect; a tap with no note near costs you",
  "lesson.talent.over": "Your mark places you among the acts, for prize money. At 50% or more the room thinks better of you; at 80% or more the warden's goodwill takes 20% heat off. And the music drowns noise in the canteen",
  "lesson.talent.late": "Talent night is over. Try the lesson again",
  "lesson.talent.off": "Your act was cut short. Try the lesson again",
  "lesson.quiz.t": "Quiz night",
  "lesson.quiz.d": "Eight questions against three inmates",
  "lesson.quiz.join": "It's quiz night. At one of the four places in the library, press Join: the three inmates nearest come over to play",
  "lesson.quiz.answer": "Answer with 1–4 (or click). Each question is yours alone for a few seconds while it's read; then the first right answer takes the point. Answer wrong and you're out of that question",
  "lesson.quiz.answerTouch": "Tap an answer. Each question is yours alone for a few seconds while it's read; then the first right answer takes the point. Answer wrong and you're out of that question",
  "lesson.quiz.play": "Half the questions are about famous escapes, half about this prison: its timetable, its guards, what you can craft. Play it out",
  "lesson.quiz.over": "Most points wins $30 and +2 Intellect. From Intellect 60, a wrong answer is ruled out for you: reading pays",
  "lesson.quiz.late": "Quiz night is over. Try the lesson again",
  "lesson.quiz.off": "You left the quiz. Try the lesson again",
  "stage.firstPrize": "1st ${n}",
  "refused.quizLate": "Too late to start the quiz tonight: join by 19:30",
  "stage.quit": "Stop",
  "stage.laneAria": "Lane {n}",
  "lesson.quiz.joinTouch": "It's quiz night. At one of the four places in the library, tap Join: the three inmates nearest come over to play",

