  "lou.diversion.what.plain.0": "I need a distraction at the prison.",
  "lou.diversion.what.plain.1": "Cause a scene outside, so the guards come running.",
  "lou.diversion.what.plain.2": "Make a racket out front to pull the guards away.",
  "lou.diversion.what.coded.0": "Could you throw Grandma a surprise party?",
  "lou.diversion.what.coded.1": "Bring the brass band round, would you?",
  "lou.diversion.what.coded.2": "Time for a bit of fireworks, cousin.",
  "lou.diversion.what.deep.0": "The blue heron needs feeding.",
  "lou.diversion.what.deep.1": "Aunt Rosa's goat got out again.",
  "lou.diversion.what.deep.2": "Tell Benny the kettle's whistling.",
  "lou.diversion.how.plain.0": "Set off a car alarm at the front gate.",
  "lou.diversion.how.plain.1": "Do it right at the main gate.",
  "lou.diversion.how.plain.2": "Make the gate guards leave their posts.",
  "lou.diversion.how.coded.0": "Park the old banger by the big front door.",
  "lou.diversion.how.coded.1": "Knock on the front door, nice and loud.",
  "lou.diversion.how.coded.2": "Ring the doorbell of the big house.",
  "lou.diversion.how.deep.0": "Under the third lamp from the oak.",
  "lou.diversion.how.deep.1": "Where the swallows nest in spring.",
  "lou.diversion.how.deep.2": "By the yellow letterbox, like last time.",
  "lou.diversion.when.plain.0": "Do it at {hour} sharp.",
  "lou.diversion.when.plain.1": "Set it off at {hour}, no later.",
  "lou.diversion.when.plain.2": "At {hour} exactly, when I'm ready to move.",
  "lou.diversion.when.coded.0": "Grandma's party starts at {hour}.",
  "lou.diversion.when.coded.1": "Tell Mum supper's at {hour}.",
  "lou.diversion.when.coded.2": "The bus comes at {hour}, don't miss it.",
  "lou.diversion.when.deep.0": "When the cuckoo calls {hour}.",
  "lou.diversion.when.deep.1": "The geese fly south at {hour}.",
  "lou.diversion.when.deep.2": "At {hour}, when the cat comes in.",
  "lou.cake.what.plain.0": "Send me a cake in here.",
  "lou.cake.what.plain.1": "Bake me a cake and bring it in.",
  "lou.cake.what.plain.2": "I need a cake smuggled in.",
  "lou.cake.what.coded.0": "I'd do anything for something sweet.",
  "lou.cake.what.coded.1": "Mum's Sunday special would be lovely.",
  "lou.cake.what.coded.2": "Bring me a taste of home.",
  "lou.cake.what.deep.0": "The baker's daughter sends her love.",
  "lou.cake.what.deep.1": "Tell Mabel the oven's warm.",
  "lou.cake.what.deep.2": "The dove flies at teatime.",
  "lou.cake.how.plain.0": "Hide a metal file inside it.",
  "lou.cake.how.plain.1": "Put a file in the middle, for the bars.",
  "lou.cake.how.plain.2": "Bake a saw blade into it.",
  "lou.cake.how.coded.0": "With something crunchy in the middle.",
  "lou.cake.how.coded.1": "Extra filling. The hard kind.",
  "lou.cake.how.coded.2": "The one with the surprise inside.",
  "lou.cake.how.deep.0": "The blacksmith's recipe, mind.",
  "lou.cake.how.deep.1": "With Uncle Iron's secret ingredient.",
  "lou.cake.how.deep.2": "As crisp as the old saw by the shed.",
  "lou.cake.when.plain.0": "Smuggle it in at the next visit.",
  "lou.cake.when.plain.1": "Bring it next time you can get it in.",
  "lou.cake.when.plain.2": "Get it past the guards as soon as you can.",
  "lou.cake.when.coded.0": "Pop round when the doors open for family.",
  "lou.cake.when.coded.1": "Bring it along, next time we have tea.",
  "lou.cake.when.coded.2": "Save me a slice for the next get-together.",
  "lou.cake.when.deep.0": "When the swallows come home.",
  "lou.cake.when.deep.1": "On the day the vicar calls.",
  "lou.cake.when.deep.2": "At the next full kettle.",
  "lou.car.what.plain.0": "I need a getaway car.",
  "lou.car.what.plain.1": "Get a car ready for my escape.",
  "lou.car.what.plain.2": "Bring a car to drive me away from here.",
  "lou.car.what.coded.0": "Tune up the old jalopy for me.",
  "lou.car.what.coded.1": "Warm up Uncle's taxi.",
  "lou.car.what.coded.2": "I'll be needing a lift home.",
  "lou.car.what.deep.0": "The red pony wants shoeing.",
  "lou.car.what.deep.1": "The fox needs his coat.",
  "lou.car.what.deep.2": "Wake the sleeping tortoise.",
  "lou.car.how.plain.0": "Wait on the road outside the prison.",
  "lou.car.how.plain.1": "Park on the road past the fence.",
  "lou.car.how.plain.2": "Be outside the walls with the engine running.",
  "lou.car.how.coded.0": "Wait at the end of our street.",
  "lou.car.how.coded.1": "Park where the pavement ends.",
  "lou.car.how.coded.2": "Keep the engine warm round the corner.",
  "lou.car.how.deep.0": "Past the scarecrow, left of the moon.",
  "lou.car.how.deep.1": "Where the river forgets its name.",
  "lou.car.how.deep.2": "By the sleeping milestone.",
  "lou.car.when.plain.0": "Tonight, after lights out.",
  "lou.car.when.plain.1": "Be there tonight, late.",
  "lou.car.when.plain.2": "Tonight, between eleven and five.",
  "lou.car.when.coded.0": "After the late film tonight.",
  "lou.car.when.coded.1": "When the telly's off tonight.",
  "lou.car.when.coded.2": "After bedtime, this very night.",
  "lou.car.when.deep.0": "When the owl does the washing up.",
  "lou.car.when.deep.1": "When the moon sits on the chimney.",
  "lou.car.when.deep.2": "At the hour the hedgehog bakes.",
