  "parole.topic.work": "work",
  "parole.q.work": "Have you been working?",
  "parole.claim.work": "Every day there's work, and I meet my quota.",
  "parole.own.work": "Not as much as I should have. I know it.",
  "parole.words.work": "Work gives a day its shape. I want that outside.",
  "parole.topic.study": "courses",
  "parole.q.study": "Have you done anything to better yourself?",
  "parole.claim.study": "I've passed courses at the kiosk.",
  "parole.own.study": "Not yet. I've meant to.",
  "parole.words.study": "I read all I can. I want to learn a trade.",
  "parole.topic.family": "your family",
  "parole.q.family": "Do you keep in touch with your family?",
  "parole.claim.family": "I call home every week.",
  "parole.own.family": "Not as often as I should.",
  "parole.words.family": "They're why I want out the right way.",
  "parole.topic.favors": "the others",
  "parole.q.favors": "How do you get on with the other inmates?",
  "parole.claim.favors": "I help out where I can. Ask anyone.",
  "parole.own.favors": "I keep to myself, mostly.",
  "parole.words.favors": "Everyone in here is somebody's son. I try to remember that.",
  "parole.topic.routine": "the routine",
  "parole.q.routine": "Do you keep to the routine?",
  "parole.claim.routine": "I've never missed a roll call, a meal or a shower.",
  "parole.own.routine": "I've slipped once or twice.",
  "parole.words.routine": "A routine keeps a man straight. I've learned that.",
  "parole.topic.fights": "fights",
  "parole.q.fights": "Have you been in any fights?",
  "parole.claim.fights": "Never. I've not raised a hand.",
  "parole.own.fights": "I have, and I'm not proud of it.",
  "parole.words.fights": "I've learned to walk away. Anger never got me anything.",
  "parole.topic.contraband": "contraband",
  "parole.q.contraband": "Has anything been found on you?",
  "parole.claim.contraband": "Nothing. Not once.",
  "parole.own.contraband": "Once. It won't happen again.",
  "parole.words.contraband": "I don't need any of that. Not any more.",
  "parole.topic.solitary": "solitary",
  "parole.q.solitary": "Have you spent time in solitary?",
  "parole.claim.solitary": "Not a single night.",
  "parole.own.solitary": "I have. It taught me something.",
  "parole.words.solitary": "Time alone makes you think. I did a lot of thinking.",
  "parole.topic.heat": "the guards' word",
  "parole.q.heat": "What would the guards say about you?",
  "parole.claim.heat": "Ask them. They've nothing on me.",
  "parole.own.heat": "They'd say I've given them trouble.",
  "parole.words.heat": "I treat them with respect, and I hope it shows.",
  "parole.member.chair": "The chair",
  "parole.member.doctor": "The doctor",
  "parole.member.deputy": "The deputy warden",
  "parole.react.claim.chair": "Your file bears that out.",
  "parole.react.lie.chair": "That is not what your file says.",
  "parole.react.own.chair": "Honest, at least.",
  "parole.react.words.chair": "Well put.",
  "parole.react.wordsWeak.chair": "Words. We'd rather see deeds.",
  "parole.react.claim.doctor": "Good. Very good.",
  "parole.react.lie.doctor": "You'd lie to us now?",
  "parole.react.own.doctor": "It takes courage to say that.",
  "parole.react.words.doctor": "Thoughtful. I'll note that.",
  "parole.react.wordsWeak.doctor": "Hm. Rehearsed, I think.",
  "parole.react.claim.deputy": "My officers say the same.",
  "parole.react.lie.deputy": "My officers say otherwise.",
  "parole.react.own.deputy": "Hmph. At least you admit it.",
  "parole.react.words.deputy": "Pretty words.",
  "parole.react.wordsWeak.deputy": "Save the speeches.",
  "parole.react.silent": "The board waits. Nothing comes.",
