  "ach.backToSquareOne.d": "Have a parole application voided for plotting.",
  "look.paroleSpecs": "Reading glasses",
  "lesson.parole.t": "The parole board",
  "lesson.parole.d": "A week of good conduct, then the hearing",
  "lesson.parole.go": "You applied a week ago. The board sits at 10:00 in the visiting room: follow the arrows and take your seat",
  "lesson.parole.read": "Each member asks one question. Under it, your file shows what it says: a claim it bears out is worth most, a lie is caught. Answer with 1–3",
  "lesson.parole.readTouch": "Each member asks one question. Under it, your file shows what it says: a claim it bears out is worth most, a lie is caught. Tap an answer",
  "lesson.parole.rest": "Answer the other two. Your record and your answers together decide",
  "lesson.parole.over": "Granted: your name is on tomorrow's release list. Report to the release desk at 10:00 and walk out in your own clothes",
  "lesson.parole.late": "You missed the hearing. Try the lesson again",
  "lesson.parole.walked": "You walked out on the board. Try the lesson again",
  "lesson.parole.denied": "The board said no. Try the lesson again: read your file before you claim anything, and answer every question in time",
  "help.parole.t": "Parole",
  "help.parole.hook": "A clean record, a hearing, the front door",
  "help.parole.sum": "Apply for parole, keep a clean record for a week, then win over the board at its hearing.",
  "help.parole.tl": "Day 3 on|Apply at the release desk\nA week later, 10:00|The board sits\n10:30|The last moment to arrive\nThe next day, 10:00|Report to the release desk",
  "help.parole.steps": "From day 3, apply at the release desk, or have your lawyer file it from the pay phone ($60, a day sooner).\nFor a week, what you do goes on your record: work, courses, the routine, calls home, favors, the garden.\nOn the day, be in the room the board sits in between 10:00 and 10:30 (follow the arrows).\nThree members ask a question each; under it, your file shows what it says. Pick an answer.\nGranted: the next morning at 10:00, report to the release desk and walk out.",
  "help.parole.lh": "The three answers",
  "help.parole.list": "A claim: worth most if your file bears it out; a lie is caught.\nOwning up: a little, with most of the board.\nFine words: worth more with Intellect.",
  "help.parole.nums": "7 days|from applying to the hearing\n16|points to be granted\n3 days|to wait after a no",
  "help.parole.warn": "Fights you start, knockouts, solitary, contraband found, the evening’s heat, missed routine and a dog’s alert count against you.\nCaught plotting (digging found, cutters or a shovel on you, out at night), the application is void.",
  "help.parole.tip": "Read your file before you claim anything: a claim it bears out is the best answer there is.",
  "help.parole.more": "The board sits in the visiting room at Center Perks, in the mess hut at Stalag Flucht, and in the canteen elsewhere.\nA lockdown at 10:00 puts the hearing off a day; missing it or walking out costs you the application.\nDenied, you can apply again 3 days later, and the record starts again.\nThe release desk still checks your heat and your pockets on the morning out.\nThe Daily Escape has no parole board.",
  // ---------------------------------------------------------------- P40: the odd jobs board
