  "ach.calledIn.d": "Call in a debt from an odd job.",
  "look.copper": "Copper trim",
  "look.saffron": "Saffron trim",
  "help.oddjobs.t": "Odd jobs board",
  "help.oddjobs.hook": "Small jobs for cash, tools and favors",
  "help.oddjobs.sum": "A cork board on the canteen wall: three jobs a day, pinned up by inmates. Take one at a time, do it before its time runs out (1 to 3 days), then go back to whoever asked for your pay.",
  "help.oddjobs.lh": "The jobs",
  "help.oddjobs.list": "Lift it: a guard’s whistle from his pockets, or the head cook’s mug from the kitchen freezer.\nDrop it, or deliver: a parcel into someone’s desk without being seen, or into his hands.\nThe frame-up: plant a stash in a rival’s desk; the guards come to search it at 19:00.\nFix the game: lose (or win) an arm-wrestle, a hand of Cheat or a game of checkers.\nRat mail, the tip-off, the errand: a note by rat, an anonymous call, sugar from a merchant.\nThe birthday cake, the lookout: a cake through visiting; keep watch while someone digs.",
  "help.oddjobs.lh2": "Stories",
  "help.oddjobs.list2": "Each prison has one story: three jobs for one inmate, from day 2, a step a day.\nIts card is pinned beside the others, and short cards tell what happens.\nFinish one and you earn a new jumpsuit trim.",
  "help.oddjobs.nums": "1–3 days|to do a job\n$15–55|its pay (the fixer’s up to $83)\n19:00|a frame-up’s search\n15 min|a lookout’s dig",
  "help.oddjobs.tip": "Some jobs end with a rare item, or a debt: he’ll join your crew whatever he thinks of you, or hand over a tool when you call it in.",
  "help.oddjobs.warn": "Fail (out of time, seen, the wrong result) and whoever asked thinks less of you. A frame-up caught out: +35% heat.",
  "help.oddjobs.more": "The fixer has a job of his own each day: ask him in free time (opinion 50).\nOn watch for a dig, whistle (%KeyB%, or the job’s chip) as soon as a guard comes near.\nThe job’s chip shows the step you’re on; your file’s Today lists every step.\nTaken from 18:00, a job’s days count from the next morning. Done in time (or what you bring in hand by 08:00), it waits for you to hand it in.",
  "lesson.oddjob.t": "Odd jobs",
  "lesson.oddjob.d": "One job from the odd jobs board, start to finish",
  "lesson.oddjob.board": "The cork board on the canteen wall is the odd jobs board. Stand in front of it.",
  "lesson.oddjob.take": "Each card says who asks, what for, how long and the pay. Take the Delivery.",
  "lesson.oddjob.give": "The parcel is in your pockets. Follow the arrows to the inmate it's for, talk to him (%KeyE%) and give it to him.",
  "lesson.oddjob.giveTouch": "The parcel is in your pockets. Follow the arrows to the inmate it's for, tap him to talk and give it to him.",
  "lesson.oddjob.back": "Delivered. Now back to whoever asked: talk to him and hand the job in.",
  "lesson.oddjob.over": "Paid! New jobs every morning, one at a time. The fixer has his own, and each prison has a story.",
  "lesson.oddjob.wrong": "That's not the Delivery: try the lesson again.",
  "lesson.oddjob.lost": "The job is gone: try the lesson again.",
  "rumor.boardJob": "{inmate} pinned a job on the board today.",
  "oddjob.chain.center-perks.title": "Doc's watch",
  "oddjob.chain.center-perks.0": "Doc lost his late wife's pocket watch. Mouse hears everything: take him this parcel and ask.",
  "oddjob.chain.center-perks.1": "Mouse says a guard picked it up in the yard and keeps it in his pocket. Get it back for Doc.",
  "oddjob.chain.center-perks.2": "Doc has his watch back and wants a proper game: beat him at checkers, no pity.",
  "oddjob.chain.center-perks.0.done": "Mouse tucks the parcel away: “A guard has it. Ask Doc to be patient.”",
  "oddjob.chain.center-perks.1.done": "Doc holds the watch to his ear. It still ticks. He says nothing for a long time.",
  "oddjob.chain.center-perks.2.done": "“Fair and square,” says Doc. “I owe you one, kid.”",
  "oddjob.chain.stalag-flucht.title": "Ferret's tunnel",
  "oddjob.chain.stalag-flucht.0": "Ferret needs a spade, and the cook trades one for sugar. Buy a bag from Kipper.",
  "oddjob.chain.stalag-flucht.1": "The spade is his. Ferret digs under his bunk tonight: keep watch at his door.",
  "oddjob.chain.stalag-flucht.2": "Nobby has been talking to the guards. Plant this stash in his desk before he talks again.",
  "oddjob.chain.stalag-flucht.0.done": "The cook weighs the sugar in his hand and nods. The spade is under the potatoes.",
  "oddjob.chain.stalag-flucht.1.done": "Ferret wipes his hands. “Another foot. Not a soul saw.”",
  "oddjob.chain.stalag-flucht.2.done": "Nobby spends the night explaining himself. Ferret gives you his best spade.",
  "oddjob.chain.shankton.title": "The Preacher's collection",
  "oddjob.chain.shankton.0": "Weasel cheated the Preacher out of the chapel's collection at cards. Win it back off him at Cheat.",
  "oddjob.chain.shankton.1": "The Preacher sends the money to Smokes, who still owes it to the chapel. Hand him this parcel.",
  "oddjob.chain.shankton.2": "Weasel keeps marked cards in his cell. One anonymous call should end that.",
  "oddjob.chain.shankton.0.done": "Weasel turns his last card over and swears. The Preacher counts every coin twice.",
  "oddjob.chain.shankton.1.done": "Smokes weighs the parcel and grins. “Tell the Preacher we're square.”",
  "oddjob.chain.shankton.2.done": "The guards turn Weasel's cell inside out. “Bless you,” says the Preacher. “I owe you.”",
  "oddjob.chain.san-pancho.title": "Toro's birthday",
  "oddjob.chain.san-pancho.0": "It's Toro's birthday soon, and there's a party to brew for. Buy a bag of sugar from Flaco.",
  "oddjob.chain.san-pancho.1": "No party without a cake. Toro's sister brings one at the next visit: get it inside.",
  "oddjob.chain.san-pancho.2": "Toro wants an arm-wrestle on his birthday, and he wants to win. Let him.",
  "oddjob.chain.san-pancho.0.done": "Flaco hands over the sugar with a wink. The brew bubbles under Toro's bunk.",
  "oddjob.chain.san-pancho.1.done": "The cake has his name on it in pink icing. Toro almost cries.",
  "oddjob.chain.san-pancho.2.done": "Toro raises your arm with his. “Best birthday inside!” He gives you a screwdriver.",
  "oddjob.chain.irongate.title": "Gull's message ashore",
  "oddjob.chain.irongate.0": "Gull signals his brother on the mainland with a guard's whistle at night. Lift one.",
  "oddjob.chain.irongate.1": "His brother answered. Gull needs this parcel to reach Kipper, unseen: slip it into his desk.",
  "oddjob.chain.irongate.2": "Barnacle watches the shore at night. Keep him busy at checkers, and let him win.",
  "oddjob.chain.irongate.0.done": "Three short, one long. Out on the water, a light blinks back.",
  "oddjob.chain.irongate.1.done": "Kipper finds the parcel and nods to Gull across the canteen.",
  "oddjob.chain.irongate.2.done": "Barnacle crows over his win while the boat slips by. “I owe you,” says Gull.",

