  "ach.cleanGetaway": "Clean Getaway",
  "ach.cleanGetaway.d": "Keep running after an escape and reach safety.",
  "ach.withoutTrace": "Without a Trace",
  "ach.withoutTrace.d": "A clean getaway without being spotted once, not even in the helicopter's light.",
  "ach.changeOfClothes": "Change of Clothes",
  "ach.changeOfClothes.d": "A clean getaway in clothes taken off a washing line.",
  "ach.outOfTheLight": "Out of the Light",
  "ach.outOfTheLight.d": "Caught in the helicopter's searchlight, and clean away all the same.",
  "ach.getawayDriver": "Getaway Driver",
  "ach.getawayDriver.d": "Reach cousin Lou's car out there for a clean getaway.",
  "ach.longArm": "Long Arm of the Law",
  "ach.longArm.d": "Get recaptured after an escape.",
  "ach.soClose": "So Close",
  "ach.soClose.d": "Get recaptured with nine tenths of the way to safety behind you.",
  "ach.allClear": "All Clear",
  "ach.allClear.d": "A clean getaway from every prison.",
  "look.mhBeanie": "Forest beanie",
  "help.manhunt.t": "The manhunt",
  "help.manhunt.hook": "Over the wall: get clean away",
  "help.manhunt.sum": "Over the wall, the escape already counts. Keep running across the outside to safety for a clean getaway: a star on the medal shelf.",
  "help.manhunt.steps": "On the escape card, choose Keep running (Skip keeps the ending as it was).\nThe arrow at the top points the way to safety, and says how far.\nKeep out of the searchers’ cones of sight. In a hedge or a culvert, keep still: no eye finds you there (moving in it, they see you close by).\nGet there before they get you.",
  "help.manhunt.tl": "Head start|Up to 10 s if nobody saw you go\nThe alarm|Searchers out, making for where you’ll be\nSoon after|Dogs on your trail, roadblocks, the helicopter\nLater|The search widens: sharper eyes, the light over the hedges",
  "help.manhunt.lh": "What helps",
  "help.manhunt.list": "A washing line: other clothes. They know you only up close, and the dogs lose your trail (a guard’s uniform hides you a little better: swap it for them and they know you from a little further off).\nA ford washes your trail away.\nA stone thrown (%Space%, or the Stone button) draws searchers to where it lands.\nJerky, pepper or sleepy jerky for a dog in reach.\nCutters get you through a wire fence.\nCousin Lou’s car, if a call set it up, waits nearer.\nA crew member out with you keeps watch and whistles.",
  "help.manhunt.warn": "Gravel and railway lines are loud underfoot.\nThe helicopter’s light finds you anywhere but still in cover.\nA dog’s nose finds you close by, hidden or not, and it follows your trail.",
  "help.manhunt.nums": "10 s|head start at most\n3 tiles|they know you in other clothes\n60 s|your trail stays fresh",
  "help.manhunt.more": "Seen going (a lockdown, a chase, a takeover): no head start.\nOff the roads you go slower, slower still through cover.\nA guard’s uniform fools them only until the search has widened twice, clothes off a line until it has widened three times; in the helicopter’s light, nothing does.\nA searcher chasing you, or a handler whose dog has you, follows you into cover.\nA legal release (forged paperwork, parole) walks out: no manhunt.\nRecaptured, the escape still counts: the card says how close you got. Leaving a hunt counts as recaptured.\nThe Daily ends at the wall.",
  "lesson.manhunt.t": "The manhunt",
  "lesson.manhunt.d": "Over the wall at Center Perks: clean away in Lou's car",
  "lesson.manhunt.run": "You're over the wall and they saw you go. Get away from the wall into the woods: the arrow at the top points to Lou's car",
  "lesson.manhunt.hide": "A searcher is coming along the wall. Step into the thicket and keep still until he has gone by",
  "lesson.manhunt.clothes": "Take clothes off the washing line by the cottage: they'll know you only up close, and the dogs lose your trail",
  "lesson.manhunt.lou": "Now to Lou's car on the track: get in and you're away",
  "lesson.manhunt.caught": "Recaptured",
  "lesson.manhunt.caughtSub": "A searcher had you in sight too long. Try the lesson again",
  // v2.21 (P42, holidays).
