  "holiday.dayD.eggHunt": "Chocolate eggs hidden in inmates' desks and about the yard: find them before the inmates do (at 22:00, those left are theirs). Eat them or sell them. A lamb roast at dinner.",
  "holiday.dayD.waterFight": "15:00–15:30, hoses on the sports field (the exercise hour's place): a soaked guard out there sees only {n} tiles. An ice lolly at the canteen counter until 15:30; a barbecue for dinner.",
  "holiday.dayD.costumeNight": "A costume at the canteen counter, a pumpkin in the kitchen freezer, until 21:00 (carve it in the kitchen). From 19:00 the costume fools nobody, but every inmate near you laughs.",
  "holiday.dayD.christmasDay": "A present under the tree, at the canteen counter, until 22:00: give it to someone. Christmas dinner at 17:00.",
  "holiday.dayD.newYearsEve": "Fireworks at midnight: for ten minutes they muffle every noise you make to a whisper.",
  "holiday.pa.eggHunt": "Happy Easter! Eggs have been hidden around the prison. Lamb roast tonight.",
  "holiday.pa.waterFight": "Summer's here! Water fight on the sports field at three, a barbecue at dinner. Ice lollies at the counter.",
  "holiday.pa.costumeNight": "Happy Halloween. Costume night from seven, costumes at the counter. Nobody will be fooled.",
  "holiday.pa.christmasDay": "Merry Christmas, everyone! Presents under the tree, Christmas dinner at five.",
  "holiday.pa.newYearsEve": "New Year's Eve! Fireworks at midnight. Earplugs not provided.",
  "holiday.paStart.waterFight": "The hoses are on. Guards, mind your caps.",
  "holiday.paStart.costumeNight": "Costume night has begun. Kindly don't frighten the guards.",
  "holiday.paStart.newYearsEve": "Happy New Year! Ten minutes of fireworks, then bed.",
  "holiday.paEnd.eggHunt": "The egg hunt is over. Whatever was left, the inmates found.",
  "holiday.paEnd.waterFight": "Hoses off. Dry yourselves off, the lot of you.",
  "holiday.paEnd.costumeNight": "Costume night is over. Back into your jumpsuits.",
