  "help.holidays.t": "Holidays",
  "help.holidays.hook": "Easter, summer, Halloween, Christmas",
  "help.holidays.sum": "A game started during a holiday keeps it: decorations, its own day on the warden’s card, treats and trophies.",
  "help.holidays.lh": "The four holidays",
  "help.holidays.list": "Easter (Good Friday to Easter Monday): an egg hunt. Chocolate eggs hide in inmates’ desks and about the yard; eat or sell them. A lamb roast at dinner.\nSummer (July and August): a water fight on the sports field at 15:00 (the exercise hour), and soaked guards see only 2 tiles. Ice lollies, a barbecue, more heatwaves.\nHalloween (24 October to 2 November): costume night. The costume fools nobody, but inmates near you laugh and like you more. Carve a pumpkin in the kitchen.\nChristmas and New Year (15 December to 6 January): a present to give, Christmas dinner, then fireworks at midnight that muffle every noise to a whisper.",
  "help.holidays.lh2": "In Settings",
  "help.holidays.list2": "By the date: a new game takes the holiday on the calendar.\nPick one: any holiday, right now.\nOff: no holidays at all.",
  "help.holidays.nums": "Day 2|the holiday’s first day\n7 days|until it comes round again\n2 tiles|what a soaked guard sees",
  "help.holidays.tip": "Treats wait at the canteen counter (the pumpkin in the kitchen freezer): open it (at a meal, a press for the tray first) and take one, once a day, until the holiday’s day is over.",
  "help.holidays.more": "A game keeps the holiday it began with, even once the date has moved on.\nThe Daily plays without one, the same for everyone; only its decorations follow the date.\nThe Training Block keeps no holidays.\nThe decorations are only for show: nothing blocks your way.",
