  "hint.vendEat": "Now it’s in your hand: use the tool button to eat or drink it, or keep it for later",
  "hint.vendJam": "Stuck! Thump the machine to free it. It’s loud, and a guard may come and look. Walk away and your money’s gone",
  "lesson.vending.t": "The vending machine",
  "lesson.vending.d": "Buy a snack, free a stuck one",
  "lesson.vending.open": "Food, drink and a few useful things, there and then, for cash. Face the machine and press %KeyE%",
  "lesson.vending.openTouch": "Food, drink and a few useful things, there and then, for cash. Face the machine and tap the action button",
  "lesson.vending.buy": "Each row has its price and shows how many are left. Buy a soda: press 2, or click its row",
  "lesson.vending.buyTouch": "Each row has its price and shows how many are left. Buy a soda: tap its row",
  "lesson.vending.drink": "It’s in your hand. Step away with Esc and use the tool button to drink it: energy back at once",
  "lesson.vending.drinkTouch": "It’s in your hand. Close the card and use the tool button to drink it: energy back at once",
  "lesson.vending.again": "Now some chocolate. This one’s going to stick: go back to the machine and buy it",
  "lesson.vending.thump": "Stuck, and your money’s gone. Thump the machine until it drops. It’s loud, so mind the guards",
  "lesson.vending.over": "Rows are filled every morning, with extra on delivery days, and inmates buy from them too. Left stuck, it’s there for anyone who thumps it",
  "help.vending.t": "The vending machine",
  "help.vending.hook": "Snacks and toiletries, for cash",
  "help.vending.sum": "Every canteen has a vending machine. Food and drink give you energy or health straight away; toiletries are for crafting. Prison prices: more than the kiosk, but no waiting for mail call.",
  "help.vending.steps": "Face the machine and press the action button.\nChoose a row: pay, the coil turns, and it drops into your hand.\nEat or drink it with the tool button, keep it for later, or give it to someone.",
  "help.vending.lh": "What it sells",
  "help.vending.list": "Chocolate, $10: +25 energy.\nSoda, $6: +12 energy.\nCoffee, $8: +18 energy.\nCrisps, $5: +10 health.\nToothpaste, soap and talcum: for crafting.",
  "help.vending.tip": "A row holds only a few, filled every morning (one more on a delivery day), and inmates buy from it too. Now and then something sticks: thump the machine to free it, but it’s loud and a guard watching won’t like it. Left stuck, it’s there for whoever thumps it next.",
  "help.vending.more": "Others in line first? Wait your turn, or push in and pay for it in opinion, perhaps a punch.\nIt’s off in a lockdown or a drill, and dark in a power cut.",
