  "hint.menuBoard": "The menu changes every day: each dish gives its own energy, some health too. Tomorrow’s is at the bottom",
  "hint.cooler": "A cup of water: +{n} energy, then nothing more for {m} minutes. On a heatwave it cools you down at once",
  "hint.coolerGossip": "Inmates chat at the water cooler. Stand by while two are there and you’ll overhear things",
  "hint.mealMenu": "Take a tray at the serving counter, then sit at a table to eat it, once a meal. What it gives depends on the day’s dish: the menu board says",
  "hint.mealTableMenu": "Sit at a table to eat your tray, once a meal. What it gives depends on the day’s dish: the menu board says",
  "lesson.menu.t": "The menu and the water cooler",
  "lesson.menu.d": "The day's dishes, a scribble, a cup of water",
  "lesson.menu.read": "What's for dinner? Face the menu board on the wall and press %KeyE%",
  "lesson.menu.readTouch": "What's for dinner? Face the menu board on the wall and tap the action button",
  "lesson.menu.dishes": "A new dish every day, each with its own energy, some with health too. Tomorrow's is at the bottom: plan your day around a good dinner",
  "lesson.menu.scribble": "Now a prank. Check no guard is looking, then press X to scribble on the board. Inmates who see it will laugh, and like you a little more",
  "lesson.menu.scribbleTouch": "Now a prank. Check no guard is looking, then tap Scribble on it. Inmates who see it will laugh, and like you a little more",
  "lesson.menu.cooler": "Thirsty work. Go to the water cooler in the corner, face it and press %KeyE% for a cup",
  "lesson.menu.coolerTouch": "Thirsty work. Go to the water cooler in the corner, face it and tap the action button for a cup",
  "lesson.menu.over": "A cup every half hour; on a heatwave it cools you down. In free time inmates chat at the cooler: stand by while two are there and you'll overhear things",
  "help.menu.t": "The menu and the water cooler",
  "help.menu.hook": "What's for dinner, and a cup of water",
  "help.menu.sum": "The menu board on the canteen wall shows the day's breakfast and dinner. A different dish every day, each giving its own energy, some health too. The water cooler is free.",
  "help.menu.steps": "Face the menu board and press the action button: today's dishes, what each gives, tomorrow's at the bottom.\nFace the water cooler and press the action button for a cup of water.\nIn free time, stand by the cooler while two inmates chat there.",
  "help.menu.lh": "What's on",
  "help.menu.list": "The plain tray: +35 energy, as it always was.\nA good day: up to +45 energy.\nSome dishes give health back too.\nMystery meat: +15. Bad luck.\nA feast beats any dish: +70, and health to full.",
  "help.menu.tip": "A cup of water gives +5 energy, then nothing more for half an hour. On a heatwave it cools you down at once, as a shower does.",
  "help.menu.warn": "Scribble on the board for a laugh, once a day: inmates who see it like you a little more. A guard who sees you at it tells you off: +10% heat.",
  "help.menu.more": "The first day always serves the plain tray.\nThe scribble is wiped every morning.\nInmates stop at the cooler from the second day. What you overhear goes into your file.",
