  "use.sleepy_jerky": "Thrown to a guard dog, it puts it to sleep",
  "use.rat_trap": "Set down for the night, it may catch a rat",
  "use.caught_rat": "Feed it {n} times and it's yours",
  "use.soap": "Washes your scent off, where there are dogs",
  "use.duct_tape": "Over a camera's lens, it blinds it for a while",
  "use.toothpaste": "Over a camera's lens, it blinds it for a while",
  "use.pruno": "Drink it: tipsy for a while, and a guard who sees it minds",
  "use.pruno_bag": "Ferments into pruno in a desk or a toilet tank",
  "use.rat_track": "Your rat runs laps on it and gets faster",
  "use.veg_seeds": "Planted in a garden bed",
  "use.fruit_seeds": "Planted in a garden bed",
  "use.plastic_cup": "Waters a garden bed",
  "use.hollow_book": "Hides one small item inside",
  "use.tattoo_gun": "For tattoos: each takes a jar of ink",
  "use.guitar": "For talent night",
  "use.dirt": "Evidence: flush it down a toilet or hide it",
  "use.wall_chunk": "Evidence: flush it down a toilet or hide it",
  "use.gift": "Give it to an inmate",
  "use.pumpkin": "Carved into a lantern in the kitchen",
  "fact.sold": "A merchant buys it for ${n}",
  "fact.oddjob": "For an odd job",
  "use.mop": "For the janitor’s job: it mops from your pockets",
  "use.fake_id": "In a guard’s uniform, shown at the checkpoint’s window at the shift change (19:50 to 20:10)",
  "use.forged_release": "Slipped into the tray at the release desk, unseen: your name on tomorrow’s list",
  "use.costume": "For costume night: it fools no one",
  "use.own_clothes": "Your own clothes, handed back on the morning you’re let out",
  // 2.36: The Six Hunter (docs/phases/9-six-hunter.md).
  "security.6": "hunting grounds",
  "prison.six-hunter": "The Six Hunter",
  "prisonInfo.six-hunter": "A hunting lodge in a pine valley, run by six Hunters and their hounds: every trail is followed, tunnels flood under the river, and the only ways out lead past the pack.",
  "warden.six-hunter": "Master Thursby",
  "pa.hello.six-hunter.0": "Morning, hares. The Master of the Hunt speaking. The hounds have had breakfast. Have you?",
  "pa.hello.six-hunter.1": "Master Thursby here. Fine tracking weather. Make of that what you will.",
  "pa.hello.six-hunter.2": "Good morning, Six Hunter. The tally board has been dusted. Nobody's on it today. Yet.",
  "pa.first.six-hunter": "Welcome to the Six Hunter, new hare. Run if you like. The Six do so enjoy a run.",
  "pa.quip.six-hunter.0": "Will whoever taught the bloodhound to howl the national anthem please stop.",
  "pa.quip.six-hunter.1": "The river is not a shortcut. It is a river.",
  "pa.quip.six-hunter.2": "Reminder: the antlers in the Trophy Hall are not for borrowing.",
  "parole.room.six-hunter": "the gatehouse",
  "oddjob.chain.six-hunter.title": "The seventh Hunter",
  "oddjob.chain.six-hunter.0": "Hare wants his name on the Hunters' tally. First, a Hunter's hunting watch: lift it, and the Six will know someone out-stalked them.",
  "oddjob.chain.six-hunter.1": "Every Hunter needs a hide. Hare's digging one under his bunk: keep watch, and whistle when a Hunter comes.",
  "oddjob.chain.six-hunter.2": "A Hunter needs a reputation. Hare's bet the whole wing you'll beat Boar at arm-wrestling. Don't make him a liar.",
  "oddjob.chain.six-hunter.0.done": "Hare winds the watch and grins. “Tick-tock, Hunters. The hare's got your time.”",
  "oddjob.chain.six-hunter.1.done": "Fell walks past whistling. Hare's hide stays a hide. He chalks a little seventh line on the wall.",
  "oddjob.chain.six-hunter.2.done": "Boar's arm hits the table and the wing roars. Hare presses an aniseed-soaked sock into your hand: “Seventh Hunter's honour.”",
  "zone.kennels": "Kennels",
  "zone.smokehouse": "Smokehouse",
  "zone.boathouse": "Boathouse",
  "job.kennels": "Kennel hand",
  "job.smokehouse": "Smokehouse",
  "job.nets": "Net mender",
  "jobTask.kennels": "Feed bin → trough → bowl bin, {n} bowls (the pack fed from your hands)",
  "jobTask.smokehouse": "Freezer → smoker → counter, {n} smoked fish",
  "jobTask.nets": "Net bin → net frame → mended bin, {n} nets",
  "thing.trough": "feeding trough",
  "thing.smoker": "smoker",
  "thing.netFrame": "net frame",
