  "city.person.fence.name": "Rook",
  "city.person.nurse.name": "Imani",
  "city.person.mechanic.name": "Kasia",
  "city.person.ranger.name": "Tomas",
  "city.person.fence.role": "Fence, off the same bus",
  "city.person.nurse.role": "Nurse",
  "city.person.mechanic.role": "Mechanic",
  "city.person.ranger.role": "Ranger",
  "city.person.fence.met": "Well. Number four off the bus. I’m Rook; I was number three. I didn’t wait for you, and you’d not have waited for me.",
  "city.person.fence.ask0": "I’ve the key to the police armoury. Don’t ask. Three bits of cloth to filter the still and it’s yours.",
  "city.person.fence.done0": "A deal’s a deal: the armoury key. Whatever’s left in there, you’re welcome to it.",
  "city.person.fence.ask1": "Two batteries. My radio only gets one woman, and she doesn’t like me.",
  "city.person.fence.done1": "That’ll do. Take the crowbar. The other four went north, for the wall. I heard the fence sing for a minute. Then it stopped.",
  "city.person.fence.idle": "Still alive, four? Then we’re both doing better than the driver.",
  "city.person.nurse.met": "You’re not bitten. Good. I’m Imani. I ran the night ward until the night ward ran itself.",
  "city.person.nurse.ask0": "Empty bottles, two of them, for boiled water. I’ll show you how to pack a proper kit for it.",
  "city.person.nurse.done0": "Watch: two bandages, the pills, tape round the lot. A medkit. It puts you back on your feet.",
  "city.person.nurse.ask1": "Ten of them, put down for good. Some were my patients. They’d thank you.",
  "city.person.nurse.done1": "Ten. I counted with you. Take these; you’ll need them where you’re going.",
  "city.person.nurse.idle": "Sleep behind boards, eat before dark, and don’t be brave. That’s all the medicine there is.",
  "city.person.mechanic.met": "Mind the oil. Kasia. I fix things; lately it’s mostly doors.",
  "city.person.mechanic.ask0": "Two bits of scrap sheet. I’ll show you what a blade and a pipe are really for.",
  "city.person.mechanic.done0": "Two blades on a pipe, taped tight, at a bench: a cleaver. It goes through more than it should.",
  "city.person.mechanic.ask1": "A can of fuel. The generator is all that keeps this door shut at night.",
  "city.person.mechanic.done1": "That’s three more nights. Planks and nails: take them, and board yourself in somewhere.",
  "city.person.mechanic.idle": "If it rattles, tape it. If it still rattles, hit it.",
  "city.person.ranger.met": "Easy. Tomas. This was the quiet posting. It still is, by day.",
  "city.person.ranger.ask0": "Dried food, two packs. I’ll give you the garden for it, and a recipe that kept patrols walking.",
  "city.person.ranger.done0": "Dried food, fruit and chocolate, pressed together: a trail ration. A day’s walking in your pocket.",
  "city.person.ranger.ask1": "Fifteen of them down. The big ones come out from the fifth night; thin the rest before they do.",
  "city.person.ranger.done1": "Fifteen. Take the spear. It keeps them a step further off, and a step is a lot.",
  "city.person.ranger.idle": "They don’t like open ground by day. At dusk, they stop minding.",
