  "city.obj.key": "Get the armoury’s key from Rook: Shopping mall, {where}",
  "city.obj.locked": "{what}: in the police armoury, locked",
  "city.say.people": "You’re not the only one, by the way. A fence in the mall, who has the police armoury’s key. A nurse, a mechanic, a ranger. They’re in your journal. They’ll want things; everyone does.",
  "city.say.met": "You found one of them. Be nice. They’ve been alone longer than you have.",
  "city.say.key": "The armoury key. Whatever Rook wanted for it, it was cheap.",
  "city.say.locked": "That’s the armoury’s. Locked, and the man with the key is in the mall.",
